import{_ as a,c as e,o as s,af as t}from"./chunks/framework.BKeRpnBD.js";const d=JSON.parse('{"title":"杂卦传","description":"周易尚氏学 - 杂卦传","frontmatter":{"title":"杂卦传","description":"周易尚氏学 - 杂卦传"},"headers":[],"relativePath":"zh/classics/shangshi/074.md","filePath":"zh/classics/shangshi/074.md"}'),r={name:"zh/classics/shangshi/074.md"};function i(n,p,c,_,o,l){return s(),e("div",null,[...p[0]||(p[0]=[t('<h1 id="杂卦传" tabindex="-1">杂卦传 <a class="header-anchor" href="#杂卦传" aria-label="Permalink to “杂卦传”">​</a></h1><p>十翼以杂卦终。与山六十四卦以未济终义同也。盖六十四卦卦序皆文王所定。其起讫皆有深义不可动摇。然易道以不穷为义。六十四卦至既济而六爻定。定则穷矣。故殿以未济。使之复通。六十四卦。上经始天地。下经始夫妇。此不易者也。故杂卦仍之。而以井困居上经之末。以损益为枢纽。以未济夬居下经之末。以否泰为枢纽。损益否泰。后先互易。明文王之意。先天道。后人事。孔子之意。先人事后天道也。先人事。并取其不穷。困而不失其亨。故以为上经之殿。听天道。则事之济不济命也。刚健果决。自强不息。终焉以赴之耳。故以未济夬终。仍穷变通久之义也。谓之为杂者。言杂柔（左未）各卦。使上下经互易。不与文王卦序同。非孔子不敢有此改作。亦非孔子无此神化之笔也。彼七十二贤固不敢创制如斯也。以上所言。杂卦殿十翼之义也。至其所言。必错综对举者何也。以见卦象正则如此。反则如彼也。正象说卦举其端。说卦所未言者。可类推也。至覆象则无言者。然如大过九五枯杨。人尚知为反巽。独正覆象相杂。如蒙匪我求童蒙。童蒙求我。初筮告。再三读。读则不告。则以二至上。正反震也。如左传以谦为败言。则以谦下艮。与震相反也。如困曰有言不信。则以三至上。正覆兑也。如震曰婚媾有言。则以二至上正覆震相背也。如中孚曰鹤鸣子和。则以二至五正反震相对。如相应也。鸣鹤在阴者。则以二至五正反民。正则为山阳。反则为山阴也。又六三云。或鼓或罢。或泣或歌。则以二至五正反艮震。震则或鼓或歌。艮则或泣或罢也。如此之类。经内甚多。除焦氏易林外。二千年说者无不误。夫子盖预知之。故于最后之杂卦申其义。</p><p>乾刚坤柔。比乐师忧。</p><p>比五虽坎。然当位居尊。故乐。师二人渊。故忧。</p><p>临观之义。或与或求。</p><p>临二阳抚临万民。有施惠之意。震往。故曰与。反之为观。则万民仰五。有乞求之意。故曰求。艮为求也。</p><p>屯见而不失其居。蒙杂而着。</p><p>屯二阳皆当位。故不失其居。蒙二阳皆失位。故曰杂。物相杂则文生。故曰着。</p><p>震起也。艮止也。损益盛衰之始也。</p><p>震动故起。反则止矣。泰损上一阳以益上。故损为衰之始。再三损则成否否移上一阳以益下。故益为盛之始。再三益则成泰。</p><p>大畜时也。无妄灾也。</p><p>王引之云。古时与待通。恐天灾至。畜以待饥。人本坤灵图。无妄互艮。艮为火。故灾。焦京皆以无妄为大旱卦。自艮火象失传。虞氏即不知其义。</p><p>萃聚而升不来也。谦轻而豫怠也。</p><p>阳上升。故不来。廉不自满。故轻。豫自足。故怠。怠虞作怡。按怠怡皆从心。本一字。故古常通用。史记始皇本纪。视听不怠。刘歆烈女赞。言行不怠。注并作怡。怡则自足。与谦轻反。</p><p>噬嗑食也。贲无色也。兑见而巽伏也。</p><p>颐中有物。故曰食。火在山下。与明夷同。故曰元色。兑阴在上故曰见。巽阴在下故曰伏。故巽亦为盗贼。为寇戎。为豕。与坎同象。</p><p>随元故也。蛊则饬也。剥烂也。复反也。晋昼也。明夷诛也。</p><p>志在随时。不执其故。广韵。饬整备也。蛊则饬者。乱极思治也。烂自姤始。至剥而极。复则阳反。曰在上故昼。诛伤也。明伤则夜矣。</p><p>井通而因相遇也。</p><p>并养而不穷故通。困刚掩。阳陷阴中。不通。自乾坤至此仍三十卦。合上经数。自咸恒至夬。仍三十四卦。合下经数。</p><p>咸速也。恒久也。涣离也。节止也。</p><p>感则无远近。无弗届。故事莫速于感。反之为恒。则不速而久。涣者散也。故曰离。反之为节。则合而不离。故曰止。</p><p>解缓也。蹇难也。睽外也。家人内也。</p><p>缓则和矣。和则易矣。反之则难。睽离女在上卦。故曰外。反之在内。故曰内也。</p><p>否泰反其类也。</p><p>阴阳交为类。否阴交阳。泰阳交阴。故曰反。</p><p>大壮则止。遁则退也。大有众也。同人亲也。</p><p>止则不退。反之则退。众则不亲。反之则亲。</p><p>革去故也。鼎取新也。小过过也。中孚信也。</p><p>革更改旧有。故曰去故。鼎亨饪待熟。故曰取新。过失也。失刖不信。反之则信。</p><p>丰多故也。亲寡旅也。离上而坎下也。</p><p>多与寡相反。上与下相反。丰雷电皆至故多。旅互巽为寡。艮为鳏。故亲寡。火炎上。水润下。</p><p>小畜寡也。履不处也。需不进也。讼不亲也。</p><p>小畜巽为寡。履者行也。故不处。需险在前。故不进。讼天水违行。故不亲。寡则独处。反之则不处矣。不亲则异行。与需之不行。亦正相反。</p><p>大过颠也。姤遇也。柔遇刚也。</p><p>颠陨也。下巽陨落。顶灭泽中。故颠。姤坤遇乾。乾刚坤柔。</p><p>渐女归待男行也。颐养正也。既济定也。</p><p>渐阴皆居阳后。故待男行。颐求口食。得养之正。既济山六爻当位而止其所。故曰定。</p><p>归妹女之终也。未济男之穷也。</p><p>女终夫家。故以嫁为终。既济三阳皆比阴。内刚外柔。与泰理同。故不穷。未济三阳皆居阴前。内柔外刚。与否理同。故穷。程子谓三阳不当位故穷。岂知三女亦不当位。岂独三男。然而不穷者。以三女皆承阳也。程子谓来之多年。不得其义。后得之于成都箍桶者。盖托辞也。</p><p>夬决也。刚决柔也。君子道长。小人道忧也。</p><p>沈善登云。杂卦以乾刚坤柔始。以夬刚决柔。还复为乾终。是举全易浑成一乾。按此说最得夬卦居终之义。自大过以下。不两卦反对。宋儒颇疑为错简。然曰女之终。男之穷。上下对文。似非错简。惟义仍反对。大过死。反之则得养。姤柔遇刚。反之则刚决柔。渐女有待而行。反之则不待而嫁矣。既济定。穷则不定。虽不对举。而义仍反对。虞翻谓大过死。大过下姤。故次以后。上夹故以决终。亦可参考。</p>',42)])])}const f=a(r,[["render",i]]);export{d as __pageData,f as default};
